INSERT INTO page_sections (id, page_id, section_type, content, settings, sort_order, is_visible, created_at, updated_at)
VALUES
  ('home-hero', 'page-home', 'hero', '{"badge":"Welcome to APG School","heading":"A bright beginning for every learner","description":"At APG Matriculation Higher Secondary School, we nurture curiosity, confidence and a lifelong love of learning. Visit us on FCI Road, Ganapathy, Coimbatore.","primary_btn_text":"Discover Our School","primary_btn_link":"/about","secondary_btn_text":"Admissions Enquiry","secondary_btn_link":"/admissions","image_url":"https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=1600&auto=format&fit=crop&q=85","stats":[{"label":"Learning","value":"Every day"},{"label":"Our community","value":"Growing together"},{"label":"Location","value":"Coimbatore"}]}'::jsonb, '{"background_style":"gradient","padding_y":"spacious","alignment":"center"}'::jsonb, 0, TRUE, NOW(), NOW()),
  ('home-values', 'page-home', 'bento_grid', '{"badge":"The APG Experience","heading":"Room to learn. Support to thrive.","description":"A school experience built around strong foundations, thoughtful guidance and opportunities to explore.","items":[{"title":"Strong foundations","desc":"Build understanding and confidence through a supportive learning environment.","icon":"Layers","badge":"Learning"},{"title":"Curious minds","desc":"Encourage questions, discovery and a habit of learning beyond the classroom.","icon":"Sparkles","badge":"Explore"},{"title":"Character & care","desc":"Grow respect, responsibility and kindness as part of everyday school life.","icon":"Shield","badge":"Values"},{"title":"A place to belong","desc":"Help every child feel welcomed, known and encouraged to do their best.","icon":"Activity","badge":"Community"}]}'::jsonb, '{"background_style":"dark","padding_y":"spacious","alignment":"center"}'::jsonb, 1, TRUE, NOW(), NOW()),
  ('home-about', 'page-home', 'about', '{"badge":"Who We Are","heading":"Learning with purpose, growing with confidence","description":"APG Matriculation Higher Secondary School is a learning community serving families in Ganapathy, Coimbatore. We aim to help students develop academically and personally, with care, encouragement and a sense of belonging.","image_url":"https://images.unsplash.com/photo-1509062522246-3755977927d7?w=1200&auto=format&fit=crop&q=85","points":["A welcoming and supportive school community","Learning that builds strong foundations","Encouragement to explore interests and talents","A focus on confidence, respect and responsibility"],"cta_text":"More About APG","cta_link":"/about"}'::jsonb, '{"background_style":"muted","padding_y":"spacious","alignment":"center"}'::jsonb, 2, TRUE, NOW(), NOW()),
  ('home-academics', 'page-home', 'services', '{"badge":"Learning at APG","heading":"Growing through every stage","description":"A broad school journey that supports students as their interests and abilities develop.","items":[{"title":"Foundational learning","desc":"Build confidence, communication and essential skills in the early years.","icon":"Sparkles"},{"title":"Middle school","desc":"Strengthen core subject knowledge and encourage independent thinking.","icon":"BookOpen"},{"title":"Secondary education","desc":"Develop focus, subject depth and readiness for the next step.","icon":"GraduationCap"},{"title":"Higher secondary","desc":"Support students as they pursue their academic goals and future plans.","icon":"Target"}]}'::jsonb, '{"background_style":"default","padding_y":"spacious","alignment":"center"}'::jsonb, 3, TRUE, NOW(), NOW()),
  ('home-campus', 'page-home', 'projects', '{"badge":"A Day at School","heading":"More than lessons","description":"Learning also happens through discovery, creativity, friendship and shared experiences.","items":[{"title":"Learn together","category":"Classrooms","desc":"A positive space for participation, practice and new ideas.","image_url":"https://images.unsplash.com/photo-1509062522246-3755977927d7?w=1200&auto=format&fit=crop&q=85"},{"title":"Discover more","category":"Learning spaces","desc":"Encouraging reading, research and a curious outlook.","image_url":"https://images.unsplash.com/photo-1507842217343-583bb7270b66?w=900&auto=format&fit=crop&q=85"},{"title":"Explore and experiment","category":"Hands-on learning","desc":"Make room for observation, questions and discovery.","image_url":"https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=900&auto=format&fit=crop&q=85"}]}'::jsonb, '{"background_style":"default","padding_y":"spacious","alignment":"center"}'::jsonb, 4, TRUE, NOW(), NOW()),
  ('home-cta', 'page-home', 'cta', '{"heading":"Come and get to know APG","description":"We welcome families to learn more about our school and admissions. Find us at FCI Road, Ganapathy, Coimbatore.","primary_btn_text":"Admissions Enquiry","primary_btn_link":"/admissions","secondary_btn_text":"Contact the School","secondary_btn_link":"/contact"}'::jsonb, '{"background_style":"default","padding_y":"spacious","alignment":"center"}'::jsonb, 5, TRUE, NOW(), NOW()),
  ('about-hero', 'page-about', 'hero', '{"badge":"About Our School","heading":"A community where every learner matters","description":"APG Matriculation Higher Secondary School is located at FCI Road, Ganapathy, Coimbatore. We believe children learn best when they feel supported, inspired and encouraged to take part.","image_url":"https://images.unsplash.com/photo-1529390079861-591de354faf5?w=900&auto=format&fit=crop&q=85","primary_btn_text":"Explore Academics","primary_btn_link":"/academics"}'::jsonb, '{"background_style":"gradient","padding_y":"spacious","alignment":"center"}'::jsonb, 0, TRUE, NOW(), NOW()),
  ('about-story', 'page-about', 'rich_text', '{"title":"Our approach","content":"<p>School is a place to discover strengths, ask questions and build the knowledge that opens new possibilities. At APG, we value consistent effort, thoughtful teaching and a caring relationship between students, families and educators.</p><p>We encourage students to take pride in their progress, respect one another and approach each new challenge with confidence.</p>"}'::jsonb, '{"background_style":"default","padding_y":"spacious","alignment":"center"}'::jsonb, 1, TRUE, NOW(), NOW()),
  ('about-approach', 'page-about', 'bento_grid', '{"badge":"Our Values","heading":"Guided by care and high expectations","description":"The habits and values we practice help create a positive place to learn.","items":[{"title":"Respect","desc":"Listen, care for others and value different perspectives.","icon":"Shield"},{"title":"Curiosity","desc":"Ask questions and take an active part in learning.","icon":"Sparkles"},{"title":"Perseverance","desc":"Keep trying, learn from feedback and celebrate progress.","icon":"Activity"},{"title":"Responsibility","desc":"Take ownership of choices, learning and community.","icon":"CheckCircle"}]}'::jsonb, '{"background_style":"dark","padding_y":"spacious","alignment":"center"}'::jsonb, 2, TRUE, NOW(), NOW()),
  ('academics-hero', 'page-academics', 'hero', '{"badge":"Academics","heading":"A strong foundation for what comes next","description":"Learning at every stage is an opportunity to build understanding, independence and confidence.","image_url":"https://images.unsplash.com/photo-1509062522246-3755977927d7?w=1200&auto=format&fit=crop&q=85","primary_btn_text":"Ask About Admissions","primary_btn_link":"/admissions"}'::jsonb, '{"background_style":"gradient","padding_y":"spacious","alignment":"center"}'::jsonb, 0, TRUE, NOW(), NOW()),
  ('academics-programmes', 'page-academics', 'services', '{"badge":"Learning Journey","heading":"Support at every stage","description":"Our school brings students through a connected journey from early learning to higher secondary.","items":[{"title":"Primary years","desc":"Develop literacy, numeracy, communication and a positive approach to school.","icon":"BookOpen"},{"title":"Middle years","desc":"Broaden subject understanding and build strong study habits.","icon":"Layers"},{"title":"Secondary years","desc":"Deepen knowledge, apply ideas and prepare for important assessments.","icon":"Target"},{"title":"Higher secondary","desc":"Focus on chosen subjects and prepare for future study and career pathways.","icon":"GraduationCap"}]}'::jsonb, '{"background_style":"default","padding_y":"spacious","alignment":"center"}'::jsonb, 1, TRUE, NOW(), NOW()),
  ('academics-note', 'page-academics', 'about', '{"badge":"Learning Together","heading":"Learning is a partnership","description":"Students make their best progress when school and home work together. We encourage regular attendance, open communication and a steady commitment to learning.","image_url":"https://images.unsplash.com/photo-1507842217343-583bb7270b66?w=900&auto=format&fit=crop&q=85","points":["Regular attendance and a steady routine","Open communication between home and school","Encouragement to ask questions and seek support"],"cta_text":"Contact Our School","cta_link":"/contact"}'::jsonb, '{"background_style":"muted","padding_y":"spacious","alignment":"center"}'::jsonb, 2, TRUE, NOW(), NOW()),
  ('campus-hero', 'page-campus', 'hero', '{"badge":"Campus Life","heading":"A school day full of possibility","description":"Friendships, activities and new experiences help make each school day memorable.","image_url":"https://images.unsplash.com/photo-1529390079861-591de354faf5?w=900&auto=format&fit=crop&q=85","primary_btn_text":"Visit Our Campus","primary_btn_link":"/contact"}'::jsonb, '{"background_style":"gradient","padding_y":"spacious","alignment":"center"}'::jsonb, 0, TRUE, NOW(), NOW()),
  ('campus-gallery', 'page-campus', 'gallery', '{"badge":"Explore","heading":"Spaces to learn and grow","description":"A glimpse of the places and experiences that support learning and school life.","images":[{"title":"Classroom learning","url":"https://images.unsplash.com/photo-1509062522246-3755977927d7?w=1200&auto=format&fit=crop&q=85","category":"Learning"},{"title":"Reading and discovery","url":"https://images.unsplash.com/photo-1507842217343-583bb7270b66?w=900&auto=format&fit=crop&q=85","category":"Learning"},{"title":"Science and exploration","url":"https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=900&auto=format&fit=crop&q=85","category":"Learning"},{"title":"Students learning together","url":"https://images.unsplash.com/photo-1529390079861-591de354faf5?w=900&auto=format&fit=crop&q=85","category":"Community"}]}'::jsonb, '{"background_style":"default","padding_y":"spacious","alignment":"center"}'::jsonb, 1, TRUE, NOW(), NOW()),
  ('campus-life', 'page-campus', 'services', '{"badge":"Beyond the Classroom","heading":"Discover, participate, belong","description":"School life gives students opportunities to try new things and learn alongside one another.","items":[{"title":"Creative expression","desc":"Make space for imagination, ideas and self-expression.","icon":"Sparkles"},{"title":"Physical wellbeing","desc":"Encourage movement, teamwork and healthy habits.","icon":"Activity"},{"title":"Shared celebrations","desc":"Bring the school community together through events and traditions.","icon":"Globe"}]}'::jsonb, '{"background_style":"muted","padding_y":"spacious","alignment":"center"}'::jsonb, 2, TRUE, NOW(), NOW()),
  ('admissions-hero', 'page-admissions', 'hero', '{"badge":"Admissions","heading":"Begin your APG school journey","description":"We invite families to connect with us and learn about the admission process. Our campus is at FCI Road, Ganapathy, Coimbatore.","image_url":"https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=1600&auto=format&fit=crop&q=85","primary_btn_text":"Contact Admissions","primary_btn_link":"/contact","secondary_btn_text":"Explore Academics","secondary_btn_link":"/academics"}'::jsonb, '{"background_style":"gradient","padding_y":"spacious","alignment":"center"}'::jsonb, 0, TRUE, NOW(), NOW()),
  ('admissions-steps', 'page-admissions', 'services', '{"badge":"Getting Started","heading":"Three simple steps","description":"Our school team can guide you through the information you need.","items":[{"title":"Get in touch","desc":"Contact the school to share your child’s grade and ask your questions.","icon":"Phone"},{"title":"Visit and learn","desc":"Connect with our team to understand the school and its learning environment.","icon":"MapPin"},{"title":"Discuss next steps","desc":"Our team will explain the current application requirements and process.","icon":"CheckCircle"}]}'::jsonb, '{"background_style":"default","padding_y":"spacious","alignment":"center"}'::jsonb, 1, TRUE, NOW(), NOW()),
  ('admissions-faq', 'page-admissions', 'faq', '{"badge":"Helpful Information","heading":"Admissions questions","description":"For current availability, documents and timings, please contact the school directly.","items":[{"question":"Where is the school located?","answer":"FCI Road, Ganapathy, Coimbatore."},{"question":"How can I ask about available classes?","answer":"Use the contact form or call the school office to discuss the current admissions availability."},{"question":"What documents are required?","answer":"Please contact the school office for the latest document checklist and application guidance."}]}'::jsonb, '{"background_style":"muted","padding_y":"spacious","alignment":"center"}'::jsonb, 2, TRUE, NOW(), NOW()),
  ('contact-hero', 'page-contact', 'hero', '{"badge":"Contact Us","heading":"We would love to hear from you","description":"Reach the school to ask a question, discuss admissions or arrange a visit. We are located at FCI Road, Ganapathy, Coimbatore."}'::jsonb, '{"background_style":"gradient","padding_y":"spacious","alignment":"center"}'::jsonb, 0, TRUE, NOW(), NOW()),
  ('contact-form', 'page-contact', 'contact_form', '{"badge":"Get in Touch","heading":"Send an enquiry","description":"Share your question and the school team will follow up.","address":"FCI Road, Ganapathy, Coimbatore","email":"","phone":"","hours":"Please contact the school for office hours."}'::jsonb, '{"background_style":"default","padding_y":"spacious","alignment":"center"}'::jsonb, 1, TRUE, NOW(), NOW());
